        accept_candidate<<<2,256>>>(ds,4,dx,states,controls);
        CUDA(cudaGetLastError()); CUDA(cudaDeviceSynchronize());
        CUDA(cudaMemcpy(&host,ds,sizeof(host),cudaMemcpyDeviceToHost));
