        if (test==5 || test==6) REQUIRE(host.command.done && host.result.status==1);
        if (test==8) REQUIRE(record.ratio==1 && std::abs(host.trust_state-.32)<1e-15);
        if (test==9) REQUIRE(record.ratio==-1);
